1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Locale;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's region. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
29	    java.util.Map<String, String> REGION_TIMEZONE =
30	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne",
31	            "QLD", "Australia/Brisbane");
32	
33	    @Mapping(target = "displayName",
34	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
36	    @Mapping(target = "initials", expression = "java(initials(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
39	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
40	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
41	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
42	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
43	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
44	    @Mapping(target = "locality", expression = "java(locality(owner))")
45	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
46	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
47	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
48	    OwnerDto toOwnerDto(Owner owner);
49	
50	    /**
51	     * The owner's salutation: the supplied title, a single space and the last name when a
52	     * title was supplied (e.g. 'DR Who'), or just the last name when no title (null or blank)
53	     * was given.
54	     */
55	    default String salutation(Owner owner) {
56	        String title = owner.getTitle();
57	        if (title == null || title.isBlank()) {
58	            return owner.getLastName();
59	        }
60	        return title + " " + owner.getLastName();
61	    }
62	
63	    /**
64	     * The owner's age band, derived from the supplied birthDate as at the
65	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
66	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
67	     * available, so the field is omitted for owners without a supplied birth date.
68	     */
69	    default String ageBand(Owner owner) {
70	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
71	            return null;
72	        }
73	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
74	        if (age < 18) {
75	            return "MINOR";
76	        }
77	        if (age < 65) {
78	            return "ADULT";
79	        }
80	        return "SENIOR";
81	    }
82	
83	    /**
84	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
85	     * otherwise 'PHONE'.
86	     */
87	    default String contactPreference(Owner owner) {
88	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
89	        return hasEmail ? "EMAIL" : "PHONE";
90	    }
91	
92	    /**
93	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
94	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
95	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
96	     */
97	    default String locality(Owner owner) {
98	        String code = owner.getCustomerCode();
99	        if (code != null) {
100	            int dash = code.indexOf('-');
101	            if (dash > 0) {
102	                return code.substring(0, dash);
103	            }
104	        }
105	        return "UNKNOWN";
106	    }
107	
108	    /**
109	     * The owner's IANA timezone, derived from its locality/region via the fixed
110	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
111	     * QLD -> Australia/Brisbane). Returns {@code null} when the region is not one of
112	     * these, so the field is omitted for owners whose region is unknown.
113	     */
114	    default String timezone(Owner owner) {
115	        return REGION_TIMEZONE.get(locality(owner));
116	    }
117	
118	    /**
119	     * The owner's membership points. Starts at 0; gains 2 when an email address is present,
120	     * 1 when the owner has no namesakes (namesakeCount is 0), 2 for a household of 3 or more
121	     * (householdSize is 3 or greater), and 3 when the owner's tenure exceeds 365 days (more
122	     * than 365 whole days between the registrationDate and today). Because a newly created
123	     * owner has zero tenure, the tenure points are only earned once more than a year has
124	     * passed since registration.
125	     */
126	    default Integer membershipPoints(Owner owner) {
127	        int points = 0;
128	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
129	        if (hasEmail) {
130	            points += 2;
131	        }
132	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
133	        if (noNamesakes) {
134	            points += 1;
135	        }
136	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
137	            points += 2;
138	        }
139	        if (owner.getRegistrationDate() != null
140	            && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(),
141	                java.time.LocalDate.now()) > 365) {
142	            points += 3;
143	        }
144	        return points;
145	    }
146	
147	    /**
148	     * The owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
149	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
150	     * for 6 or more points.
151	     */
152	    default Integer membershipLevel(Owner owner) {
153	        int points = membershipPoints(owner);
154	        if (points <= 1) {
155	            return 1;
156	        }
157	        if (points <= 3) {
158	            return 2;
159	        }
160	        if (points <= 5) {
161	            return 3;
162	        }
163	        return 4;
164	    }
165	
166	    /**
167	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
168	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
169	     */
170	    default Integer checkDigit(Owner owner) {
171	        if (owner.getCustomerCode() == null) {
172	            return null;
173	        }
174	        String s = owner.getCustomerCode();
175	        int sum = 0;
176	        boolean dbl = true;
177	        for (int i = s.length() - 1; i >= 0; i--) {
178	            char c = s.charAt(i);
179	            if (c < '0' || c > '9') {
180	                continue;
181	            }
182	            int d = c - '0';
183	            if (dbl) {
184	                d *= 2;
185	                if (d > 9) {
186	                    d -= 9;
187	                }
188	            }
189	            sum += d;
190	            dbl = !dbl;
191	        }
192	        return (10 - (sum % 10)) % 10;
193	    }
194	
195	    /**
196	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
197	     * is the last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
198	     */
199	    default String membershipNumber(Owner owner) {
200	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
201	            return null;
202	        }
203	        return String.format("%s-M%02d", owner.getCustomerCode(),
204	            owner.getRegistrationDate().getYear() % 100);
205	    }
206	
207	    /**
208	     * Known E.164 country calling codes used to split the stored telephone into its
209	     * country code and national number for display. Longer codes are matched first so a
210	     * '+61' number is not mistaken for a '+6...' one.
211	     */
212	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
213	
214	    /**
215	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
216	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
217	     * Returns the stored value unchanged when it is {@code null} or not in the expected
218	     * '+'-prefixed all-digits E.164 form.
219	     */
220	    default String telephoneDisplay(Owner owner) {
221	        String telephone = owner.getTelephone();
222	        if (telephone == null || !telephone.startsWith("+")) {
223	            return telephone;
224	        }
225	        String digits = telephone.substring(1);
226	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
227	            return telephone;
228	        }
229	        String countryCode = COUNTRY_CODES.stream()
230	            .filter(digits::startsWith)
231	            .findFirst()
232	            .orElse(digits.substring(0, 1));
233	        String national = digits.substring(countryCode.length());
234	        StringBuilder sb = new StringBuilder("+").append(countryCode);
